'use strict';
// Lernkarten aus den Foliensätzen des Dozenten (Medienkonzeption), mit dessen Zustimmung.
// Vorschläge, erzeugt aus den Folientexten; sichtbar für Studierende erst nach Freigabe durch Lehrende.
// Fremdmaterial im Kursordner (Studien, Fachartikel, Telekom-Methodenheft) ist bewusst nicht verwendet.
const LERNKARTEN = {"MKO": {"quellen": {"01": "Einführung Medien-Konzeption","02": "Arbeitsfeld Medien-Produktion","03": "Projekt- und Team-Management","04": "Service Design","05": "User Centered Design","07": "Projekt Städelmuseum","08": "Strategische Entwicklung von Online Medien","09a": "Teil 1 Interaktions-Design","09b": "Teil 2 Homepage-Layout","09c": "Teil 3 Farbe","09d": "Teil 4 Typografie","09e": "Teil 5 Grafische Elemente in Web","09f": "Teil 6 Navigation","09g": "Teil 7 Layout-Planung","09h": "Teil 8 One-Page-Design","09i": "Teil 9 One-Page Informations-Gestaltung","10": "Prüfungsaufgabe Medienkonzeption"},"karten": [{"id": "mko-01-01","nr": "01","seite": 18,"frage": "Welche fünf strategischen Konzeptionsphasen hat ein Medienprojekt?","antwort": "Briefing, Grobkonzept, Feinkonzept, Launch und Controlling."},{"id": "mko-01-02","nr": "01","seite": 18,"frage": "Welche Phase gehört NICHT zu den strategischen Konzeptionsphasen?","richtig": "Storyboard","falsch": ["Briefing","Grobkonzept","Controlling"],"erklaerung": "Die Phasen sind Briefing, Grobkonzept, Feinkonzept, Launch und Controlling. Das Storyboard ist ein Bestandteil des Feinkonzepts."},{"id": "mko-01-03","nr": "01","seite": 20,"frage": "Was gehört zur inhaltlichen Projektentwicklung (Content-Entwicklung)?","antwort": "Main Idea, zentrale Fragestellungen, Projektbeschreibung, Gliederung des Themas in verlinkte Informationsknoten und ein inhaltlicher Strukturbaum."},{"id": "mko-01-04","nr": "01","seite": 21,"frage": "Welche Analysen zur Zielgruppe gehören in die Content-Entwicklung?","antwort": "Daten der Zielgruppe ermitteln, die Zielgruppe beschreiben, Personas beschreiben und eine Benchmarkanalyse durchführen."},{"id": "mko-01-05","nr": "01","seite": 22,"frage": "Was umfasst die strategische Projektentwicklung (Zeit, Kosten, Qualität)?","antwort": "Ideenfindung mit Kreativitätstechniken und KI, Projektziele festlegen, Machbarkeitsanalyse, Kostenschätzung und Zeitplan."},{"id": "mko-01-06","nr": "01","seite": 23,"frage": "In welcher Reihenfolge werden Entwürfe zur visuellen Strategie entwickelt?","antwort": "Vom Papierprototyp über Wireframes und Mockups bis zum Prototypen."},{"id": "mko-01-07","nr": "01","seite": 26,"frage": "Was gehört zur Entwicklung der Navigation?","antwort": "Navigationskonzept, psychologische Rahmenbedingungen, Modelle der Benutzerführung, Card-Sorting sowie Beschreibung und Visualisierung der Navigation."},{"id": "mko-01-08","nr": "01","seite": 33,"frage": "Wovon hängt laut der „ersten Einsicht“ ein erfolgreiches Medienprojekt ab?","antwort": "Vom Zusammenspiel theoretischer, gestalterischer, organisatorischer und intuitiver Faktoren."},{"id": "mko-01-09","nr": "01","seite": 36,"frage": "Warum setzen viele Agenturen auf ein standardisiertes Vorgehen?","antwort": "Es sichert einen hohen Qualitätsstandard und macht Zeit, Kosten und Ressourcen planbar, sodass man Kunden schnell Dauer und Kosten nennen kann."},{"id": "mko-01-10","nr": "01","seite": 38,"frage": "Was kennzeichnet „Genius Design“?","richtig": "Der Produzent verlässt sich allein auf sich und seine Fähigkeiten","falsch": ["Das Projekt wird aus Usability-Tests abgeleitet","Die Gestaltung folgt einem festen Agenturstandard","Eine KI entwirft die Lösung"],"erklaerung": "Genius Design gilt als schwierige Methode, weil keine Nutzerforschung einfließt. Der Gegenentwurf ist Service Design bzw. User Centered Design."},{"id": "mko-01-11","nr": "01","seite": 37,"frage": "Wie leitet man ein Online-Projekt nach Service Design bzw. User Centered Design ab?","antwort": "Konsequent aus den Bedürfnissen der User, ermittelt mit Zielgruppenforschung und Usability-Tests, um den optimalen Informations-Benefit zu erreichen."},{"id": "mko-01-12","nr": "01","seite": 14,"frage": "Was muss bei jeder Nutzung von KI in der Prüfungsleistung dokumentiert werden?","antwort": "Der verwendete Prompt und das Ergebnis, dazu Beispiele für den Einsatz in den einzelnen Phasen der Konzeption."},{"id": "mko-01-13","nr": "01","seite": 15,"frage": "Welche Entwicklungsschritte durchläuft die Prüfungsleistung?","antwort": "Mündliche Ideenentwicklung, schriftliche Ideenfixierung, Ausarbeitung, Präsentation und ein gedrucktes Konzept."},{"id": "mko-02-01","nr": "02","seite": 4,"frage": "Nenne die Arbeitsfelder in der Medienproduktion.","antwort": "Design, Programmierung, Konzeption, Projektmanagement, Marketing/Beratung, Medienmanagement, IT-Management und KI-Management."},{"id": "mko-02-02","nr": "02","seite": 10,"frage": "Welche Aufgaben hat das Projektmanagement in der Medienproduktion?","antwort": "Projektabwicklung, Koordination der Produktentwicklung (Wasserfall oder agil), Schnittstelle zwischen Kunde und Team, Kalkulation, Team-Controlling und Kostenkontrolle."},{"id": "mko-02-03","nr": "02","seite": 12,"frage": "Welche Aufgaben hat der Bereich Konzeption?","antwort": "Ideenentwicklung, Konzeption von Inhalt, Gestaltung und Technik, Informationsmodellierung, Briefing, Zielgruppen- und Konkurrenzanalyse, Grob- und Feinkonzept sowie Social-Media-Integration."},{"id": "mko-02-04","nr": "02","seite": 21,"frage": "Worauf bezieht sich User Experience?","antwort": "Vor allem auf das kognitive und emotionale Erlebnis des Users. Mediale Produkte sollen Emotionen und kognitive Einsichten hervorrufen."},{"id": "mko-02-05","nr": "02","seite": 20,"frage": "Welches Berufsbild nennt die Vorlesung als NEU in der Medienproduktion?","richtig": "Digital Screenwriting","falsch": ["Mediengestalter","Druckvorlagenhersteller","Schriftsetzer"],"erklaerung": "Neue Berufsbilder sind z. B. User Experience Design, Digital Screenwriting und KI-Mastering. Klassische Bezeichnungen wie „Mediengestalter“ gelten als fast altmodisch."},{"id": "mko-02-06","nr": "02","seite": 26,"frage": "Was müsste ein „Digital Screenwriter“ verbinden?","antwort": "Storytelling-Fähigkeiten aus Interactive Storytelling, Games und Transmedia."},{"id": "mko-02-07","nr": "02","seite": 33,"frage": "Was erwarten Medienagenturen vor allem von Mitarbeitenden?","antwort": "Übergreifendes, ganzheitliches Denken und die Fähigkeit, in interdisziplinären Teams vernetzt zu arbeiten."},{"id": "mko-02-08","nr": "02","seite": 35,"frage": "Warum sind Praxisprojekte (PTP) im dualen Studium wichtig?","antwort": "Weil man lernen muss, mit realen Kunden und ihren Problemstellungen umzugehen, nicht nur in Übungen kreativ zu sein."},{"id": "mko-03-01","nr": "03","seite": 4,"frage": "Wie definiert die DIN 69901 ein Projekt?","antwort": "Als Vorhaben, das im Wesentlichen durch die Einmaligkeit der Bedingungen in ihrer Gesamtheit gekennzeichnet ist: Zielvorgabe, zeitliche, finanzielle und personelle Begrenzung, Abgrenzung von Daueraufgaben und eine eigene Organisationsstruktur."},{"id": "mko-03-02","nr": "03","seite": 4,"frage": "Welches Merkmal gehört laut DIN 69901 NICHT zu einem Projekt?","richtig": "Dauerhafte Fortführung ohne festes Ende","falsch": ["Zielvorgabe","Begrenzte Zeit und Mittel","Spezifische Organisationsstruktur"],"erklaerung": "Ein Projekt grenzt sich gerade von dauerhaften Vorhaben ab und hat einen definierten Anfang und ein definiertes Ende."},{"id": "mko-03-03","nr": "03","seite": 10,"frage": "Welche Faustregel gilt für die Größe eines Projektteams?","antwort": "Je größer die Erfahrung des Einzelnen, desto kleiner kann das Team sein. Das erleichtert die Kommunikation im Team und mit dem Auftraggeber."},{"id": "mko-03-04","nr": "03","seite": 11,"frage": "Welche drei Kompetenzen brauchen Mitglieder eines Projektteams?","antwort": "Fachkompetenz, Methodenkompetenz und Sozialkompetenz. Erst ihre Ausgewogenheit führt zu erfolgreicher Projektarbeit."},{"id": "mko-03-05","nr": "03","seite": 14,"frage": "Was beschreibt Methodenkompetenz im Projekt?","richtig": "Eine Aufgabe zielgerichtet und planmäßig von Anfang bis Ende lösen zu können","falsch": ["Empathisch und respektvoll zu kommunizieren","Die fachlichen Fähigkeiten für die Aufgabe zu besitzen","Konflikte auszuhalten und zu lösen"],"erklaerung": "Empathie und Konfliktfähigkeit gehören zur Sozialkompetenz, fachliche Fähigkeiten zur Fachkompetenz."},{"id": "mko-03-06","nr": "03","seite": 17,"frage": "Welche Doppelrolle hat eine erfolgreiche Projektleitung?","antwort": "Sie ist zugleich Manager und Team-Moderator: Sie organisiert die Projektabschnitte, leitet Sitzungen, steuert die Kommunikation und löst Konflikte."},{"id": "mko-03-07","nr": "03","seite": 19,"frage": "Nenne Aufgaben der Projektleitung.","antwort": "Projektvorbereitung, Teamzusammenstellung, Koordination, Personalführung, Informationsfluss und Dokumentation sowie Vertretung des Projekts nach außen."},{"id": "mko-03-08","nr": "03","seite": 24,"frage": "Wer hat das Phasenmodell der Teamentwicklung entwickelt?","antwort": "Der amerikanische Psychologe Bruce W. Tuckman."},{"id": "mko-03-09","nr": "03","seite": 28,"frage": "In welcher Phase nach Tuckman führt die Profilierung Einzelner zu Konflikten?","richtig": "Storming","falsch": ["Forming","Norming","Performing"],"erklaerung": "Im Storming hat sich die Gruppe gefunden, die Rollen sind aber noch nicht festgelegt. Erst im Norming entstehen Regeln und ein Wir-Gefühl."},{"id": "mko-03-10","nr": "03","seite": 29,"frage": "Was kennzeichnet die Norming-Phase?","antwort": "Die Gruppe hat ihre Konflikte überstanden, Regeln für Arbeit und Kommunikation definiert und entwickelt eine innere Struktur und ein Wir-Gefühl."},{"id": "mko-03-11","nr": "03","seite": 26,"frage": "Was passiert, wenn Konflikte im Team aus pragmatischen Gründen unterdrückt werden?","antwort": "Sie brechen wahrscheinlich später im Projekt wieder auf, oft verstärkt."},{"id": "mko-03-12","nr": "03","seite": 33,"frage": "Was ist während der Projektabwicklung im Controlling ständig nötig?","antwort": "Ein Soll-Ist-Abgleich, um bei Abweichungen vom Plan schnell reagieren zu können."},{"id": "mko-03-13","nr": "03","seite": 36,"frage": "Welche drei Projektzielgrößen bezieht die Risikoanalyse ein?","richtig": "Qualität, Zeit und Ressourcen","falsch": ["Budget, Marketing und Design","Team, Kunde und Technik","Briefing, Konzept und Launch"],"erklaerung": "Die Risikoanalyse prüft alle drei Zielgrößen Qualität, Zeit und Ressourcen."},{"id": "mko-03-14","nr": "03","seite": 39,"frage": "Was steht in einem Projektfortschrittsbericht?","antwort": "Laufende und abgeschlossene Arbeitspakete, neue Probleme und Risiken, die Terminsituation mit Begründungen für Abweichungen und eine Prognose für den weiteren Verlauf."},{"id": "mko-03-15","nr": "03","seite": 41,"frage": "Welche Fragen klärt die Evaluation in der Abschlussphase?","antwort": "Wurden die Zielgrößen eingehalten? Sind die Mitarbeitenden zufrieden? Was war gut, was schlecht? Was machen wir im nächsten Projekt besser?"},{"id": "mko-04-01","nr": "04","seite": 8,"frage": "Wann sollen Medienproduzenten nach der Idee des Service Design zum Einsatz kommen?","antwort": "Nicht erst am Ende der Produktionskette für Werbekommunikation, sondern viel früher: bei der Entwicklung eines nutzergerechten und nachhaltigen Medienangebots."},{"id": "mko-04-02","nr": "04","seite": 17,"frage": "Was tun Service Designer?","antwort": "Sie betrachten den kompletten Prozess einer Internet-Dienstleistung und gestalten ihn für die User so reibungslos, konsistent und nachhaltig wie möglich, mit Blick auf alle Touchpoints."},{"id": "mko-04-03","nr": "04","seite": 16,"frage": "Worum geht es Unternehmen bei ihrer Online-Präsenz heute vor allem?","antwort": "Um effektive digitale Berührungspunkte (Touchpoints) mit den Kunden, nicht um irgendwie attraktive Websites. Beispiel: die DB Navigator App."},{"id": "mko-04-04","nr": "04","seite": 25,"frage": "Wie beginnt der Service-Design-Prozess nach dem Kundenbriefing?","antwort": "Mit ergebnisoffener Recherche und Marktforschung zu Problemen und Bedürfnissen der Nutzer. Daraus leitet das Team Personas und User Journeys ab und entwirft Konzeptideen."},{"id": "mko-04-05","nr": "04","seite": 27,"frage": "Wie verhält sich Service Design zum klassischen Entwicklungsprozess in Agenturen?","richtig": "Es ist ihm vorgelagert","falsch": ["Es ersetzt die Programmierung","Es folgt nach dem Launch","Es betrifft nur das Logo"],"erklaerung": "Service Designer hinterfragen zuerst die Problemstellung und recherchieren nutzerzentriert, bevor die Konzeption einer Website beginnt."},{"id": "mko-04-06","nr": "04","seite": 30,"frage": "Welche Methoden nutzen Service Designer?","antwort": "Nutzerinterviews, Personas, Customer-Journey-Beschreibungen, Marktforschung und Trendanalysen."},{"id": "mko-04-07","nr": "04","seite": 31,"frage": "Was bedeutet es, dass der Service-Design-Prozess iterativ verläuft?","antwort": "Konzept, Design und Entwicklung folgen keinem linearen Verlauf: In den Entwicklungsstadien wird immer wieder getestet, weiterentwickelt und erneut getestet."},{"id": "mko-04-08","nr": "04","seite": 34,"frage": "Was sind Sprints im Service Design?","antwort": "Zwei- bis dreiwöchige Zyklen aus der agilen Methode Scrum, in denen Teilprojekte bearbeitet werden. Danach prüfen Agentur und Kunde gemeinsam die Ergebnisse."},{"id": "mko-04-09","nr": "04","seite": 36,"frage": "Wie heißt die erste Phase des Service-Design-Prozesses oft in Agenturen?","richtig": "Verstehen & Einfühlen","falsch": ["Gemeinsam kreieren & strukturieren","Launch & Controlling","Briefing & Pitch"],"erklaerung": "In der ersten Phase sammelt ein interdisziplinäres Team Informationen zu Marke, Business, Wettbewerb und Nutzungskontext. Es folgt „Gemeinsam kreieren & strukturieren“."},{"id": "mko-04-10","nr": "04","seite": 40,"frage": "Wozu verdichtet das Team die Ergebnisse der explorativen Phase?","antwort": "Zu exemplarischen Nutzertypen und Personas, daraus entsteht eine idealtypische Customer Journey."},{"id": "mko-04-11","nr": "04","seite": 45,"frage": "Wie lässt sich Service Design zusammenfassen?","antwort": "Als ganzheitliche Gestaltung digitaler Produkte mit nutzerzentriertem, analytischem und interdisziplinärem Ansatz: Strategie, Analyse, User Experience sowie Interface- und Interaction Design."},{"id": "mko-04-12","nr": "04","seite": 46,"frage": "Was ist Design Thinking?","antwort": "Eine Methode, mit der man kreative Lösungen und Innovationen zielorientiert entwickelt."},{"id": "mko-04-13","nr": "04","seite": 59,"frage": "Welches Beispiel zeigt Service Design in der Vorlesung?","antwort": "Die App „Elderly Care“: Angehörige pflegebedürftiger Menschen sehen deren Wohlbefinden über aufbereitete Sensordaten, ohne vor Ort zu sein."},{"id": "mko-05-01","nr": "05","seite": 4,"frage": "Was ist die Grundidee des User Centered Design?","antwort": "Eine Website gelingt nur, wenn die tatsächlichen Bedürfnisse der User und der wahrscheinliche Nutzungskontext bekannt sind und in der Produktion berücksichtigt werden. Der User ist im gesamten Entwicklungs- und Nutzungsprozess „König“."},{"id": "mko-05-02","nr": "05","seite": 7,"frage": "Wie lässt sich User Centered Design kurz definieren?","antwort": "Als systematische Erfassung der Erwartungen, Anforderungen und Beurteilungen der Nutzer, in allen Entwicklungsphasen eines Projekts."},{"id": "mko-05-03","nr": "05","seite": 13,"frage": "Welche zwei Ausgangspunkte kann ein UCD-Projekt haben?","antwort": "Das Re-Design einer bestehenden Website oder die Neuentwicklung einer Website."},{"id": "mko-05-04","nr": "05","seite": 16,"frage": "Welche Methode ist typisch für Phase 1 (Analyse) eines Re-Designs?","richtig": "Web-Analytics und heuristische Analyse durch Usability-Experten","falsch": ["Paper-Prototyping","Usability-Test mit einem Klick-Dummy","Multivariate Tests im Live-Betrieb"],"erklaerung": "In der Analyse werden problematische Bereiche identifiziert: Web-Analytics, heuristische Expertenanalyse, On-Site- und Zielgruppenbefragungen."},{"id": "mko-05-05","nr": "05","seite": 18,"frage": "Welche Methoden sind typisch für Phase 2 (Konzeption/Design) eines Re-Designs?","antwort": "Scribbles und Wireframes, Benchmark-Analyse, Fokusgruppen, Paper-Prototyping, Card-Sorting und Design-Tests."},{"id": "mko-05-06","nr": "05","seite": 19,"frage": "Was passiert in Phase 3 eines Re-Designs, und wie wird getestet?","antwort": "Die Erkenntnisse werden in einen Klick-Dummy bzw. Prototypen umgesetzt und mit Usability-Tests mit Nutzern geprüft, z. B. mit Eye-Tracking und Befragung."},{"id": "mko-05-07","nr": "05","seite": 20,"frage": "Kann UCD auch im Live-Betrieb eingesetzt werden?","antwort": "Ja, um laufend Schwachstellen zu finden, etwa mit On-Site-Befragungen und multivariaten Tests."},{"id": "mko-05-08","nr": "05","seite": 25,"frage": "Was kennzeichnet quantitative Methoden?","richtig": "Das Ergebnis wird in numerischen Messwerten abgebildet, z. B. bei einer standardisierten Online-Befragung","falsch": ["Verbale Aussagen werden interpretiert","Fünf bis zehn Personen diskutieren geführt","Ein lockeres, leitfadengestütztes Gespräch"],"erklaerung": "Qualitative Methoden erfassen die User-Realität über verbale Aussagen, die interpretiert werden. Fokusgruppen und Tiefeninterviews sind qualitativ."},{"id": "mko-05-09","nr": "05","seite": 28,"frage": "Warum reichen bei qualitativen Usability-Tests wenige Testpersonen?","antwort": "Wenn z. B. zwei von acht Personen ein Problem verbalisieren, ist es erkannt, und die Ursachen lassen sich durch Nachfragen und Beobachten aufdecken. Es geht nicht um Zahlen, sondern um Beschreibung."},{"id": "mko-05-10","nr": "05","seite": 30,"frage": "Wie viel Aufwand gehört in die Research-Phase?","antwort": "Es gibt keine Faustregel für die richtige Methode. Aber: Je weniger man über die Zielgruppe weiß, desto mehr Zeit und Aufwand gehört in die Research-Phase."},{"id": "mko-05-11","nr": "05","seite": 31,"frage": "Wie viele Personen nehmen normalerweise an einer Fokusgruppe teil?","richtig": "Fünf bis zehn","falsch": ["Eine","Zwei bis drei","Mindestens 500"],"erklaerung": "Eine Fokusgruppe ist eine geführte Diskussion mit meist fünf bis zehn Personen derselben Zielgruppe, die sich in Bedürfnissen und Interessen aber unterscheiden."},{"id": "mko-05-12","nr": "05","seite": 33,"frage": "Wann ist ein Tiefeninterview besonders gewinnbringend?","antwort": "Wenn man noch wenig über die Zielgruppe weiß. Es ist ein leitfadengestütztes, lockeres Gespräch und liefert viele persönliche Erfahrungswerte, ist aber zeitaufwendig."},{"id": "mko-05-13","nr": "05","seite": 36,"frage": "Was ist Social Listening?","antwort": "Man verfolgt Online-Aktivitäten und Diskussionen von Nutzern in Social Media mit Monitoring-Apps wie Brandwatch, Sprinklr oder Talkwalker und erhält so viele unvoreingenommene Meinungen."},{"id": "mko-05-14","nr": "05","seite": 44,"frage": "Wofür eignen sich Online-Befragungen?","antwort": "Um in kurzer Zeit Meinungsbilder großer Gruppen einzuholen, meist mit geschlossenen Fragen und standardisierten Antworten."},{"id": "mko-07-01","nr": "07","seite": 7,"frage": "Was war das wesentliche Manko der Städel-Website vor dem Re-Design 2015?","antwort": "Redundanz und Unübersichtlichkeit: überladen, unzureichend strukturiert, viele Inhalte wiederholten sich an mehreren Stellen."},{"id": "mko-07-02","nr": "07","seite": 9,"frage": "Wie wurde die Navigation der Städel-Website beim Re-Design verändert?","richtig": "Von acht auf vier Hauptpunkte reduziert","falsch": ["Von vier auf acht Hauptpunkte erweitert","Durch eine reine Suchfunktion ersetzt","Auf einen einzigen Menüpunkt reduziert"],"erklaerung": "Die Medienproduzenten gliederten Inhalte und Zielgruppen neu und reduzierten die Navigation von acht auf vier Hauptpunkte."},{"id": "mko-07-03","nr": "07","seite": 14,"frage": "Was meint das Städel mit „Digitalem Schlendern“?","antwort": "Das UX-Konzept der Digitalen Sammlung: Werke sind über Schlagwörter verknüpft, der User stöbert frei nach Stimmungen, Motiven oder Fachbegriffen und wird so selbst zum Kurator."},{"id": "mko-07-04","nr": "07","seite": 17,"frage": "Wie verändert die Digitale Sammlung die Rolle des Users?","antwort": "Er kommt von einer fremdbestimmten Inhaltspräsentation zu einem subjektiv inspirierten Finden und entdeckt neue Verbindungen zwischen Kunstwerken."},{"id": "mko-07-05","nr": "07","seite": 29,"frage": "Warum enthält die Städel-App unterhaltsame Stories?","antwort": "Weil Kunstwerke auf dem kleinen Smartphone-Display kaum wirken können. Die Stories widmen sich den Details der Bilder."},{"id": "mko-07-06","nr": "07","seite": 32,"frage": "Womit erkennt der Bildscanner der Städel-App die Werke?","richtig": "Mit dem Bilderkennungssystem Vuforia","falsch": ["Mit QR-Codes neben den Bildern","Mit NFC-Etiketten","Mit GPS-Ortung im Museum"],"erklaerung": "QR-Codes schieden aus ästhetischen Gründen aus, man kann sie sich neben alten Meistern nicht vorstellen."},{"id": "mko-07-07","nr": "07","seite": 30,"frage": "Welchen Vorteil hat die Städel-App gegenüber Website und Digitaler Sammlung?","antwort": "Alle geladenen Inhalte stehen auch offline zur Verfügung."},{"id": "mko-08-01","nr": "08","seite": 3,"frage": "Nenne den Workflow der Online-Medien-Produktion in der richtigen Reihenfolge.","antwort": "Briefing, Grobkonzept, Feinkonzept, Realisierung, Usability-Tests, Launch."},{"id": "mko-08-02","nr": "08","seite": 9,"frage": "Welche wissenschaftlichen Bezugstheorien hat die Online-Medien-Produktion?","antwort": "Medienpsychologie, Mediensoziologie und Kommunikationswissenschaft."},{"id": "mko-08-03","nr": "08","seite": 12,"frage": "Welche Funktion hat das Briefing?","antwort": "Die gründliche und umfassende Information durch den Auftraggeber über alle Fakten und Hintergründe, die für das geplante Projekt wichtig sein können."},{"id": "mko-08-04","nr": "08","seite": 15,"frage": "Zu welchen Punkten braucht der Medienproduzent im Briefing Aussagen des Auftraggebers?","antwort": "Ausgangssituation, Kommunikationsziele, Zielgruppen, Medienformate sowie Budget und Zeitraum."},{"id": "mko-08-05","nr": "08","seite": 14,"frage": "Welche Frage muss im Briefing auf jeden Fall geklärt werden?","richtig": "Wie der Erfolg des Projekts überprüft werden soll","falsch": ["Welche Schriftart das Logo bekommt","Welcher Programmierer das Backend baut","Wie viele Sprints das Team plant"],"erklaerung": "Unbedingt zu klären sind u. a. der Etat, die vorgesehenen Projektphasen und wie der Projekterfolg überprüft wird."},{"id": "mko-08-06","nr": "08","seite": 18,"frage": "Was sind Projektziele?","antwort": "Inhaltlich und zeitlich definierte Endpunkte einer geplanten Entwicklung. Nur wer genau weiß, wohin er will, kann auch dort ankommen."},{"id": "mko-08-07","nr": "08","seite": 21,"frage": "Wie kalkulieren Medienproduzenten meist ihre Leistungen?","antwort": "Mit eigenen Erfahrungswerten aus früheren Projekten: Wie lange hat es gedauert, welche Stundensätze galten?"},{"id": "mko-08-08","nr": "08","seite": 25,"frage": "Welche Kreativitätstechniken zur Themenfindung nennt die Vorlesung?","antwort": "Zum Beispiel Brainstorming und Workshops, dazu Mindmapping zur Visualisierung der Projektideen."},{"id": "mko-08-09","nr": "08","seite": 30,"frage": "Was ist die „Main Idea“ eines Projekts?","antwort": "Die zentrale Idee, aus der sich alle weiteren Schritte ableiten, das konzeptionelle Leitmotiv für Inhalte und Gestaltung."},{"id": "mko-08-10","nr": "08","seite": 32,"frage": "Was bedeutet Modularisierung des Inhalts?","antwort": "Den Gesamtinhalt in einfache oder komplexe Teilsegmente aufzulösen, also ein größeres Thema in mediale Module aufzuteilen."},{"id": "mko-08-11","nr": "08","seite": 41,"frage": "Wozu dient eine Site-Map?","antwort": "Sie bildet die Hierarchie der Inhalte als Strukturbaum ab, gibt Hinweise auf Navigation und Menüpunkte und zeigt, wo Seiten liegen und wie sie verlinkt sind."},{"id": "mko-08-12","nr": "08","seite": 60,"frage": "Welche vier Merkmalsgruppen sind wichtig für die Zielgruppenanalyse?","richtig": "Demografisch, psychografisch, Verhalten, geografisch","falsch": ["Alter, Einkommen, Beruf, Hobby","Farbe, Form, Schrift, Layout","Briefing, Konzept, Launch, Controlling"],"erklaerung": "Heute reichen Alter und Einkommen allein nicht mehr: Zu berücksichtigen ist insbesondere die soziokulturelle Zugehörigkeit, z. B. über Sinus-Milieus."},{"id": "mko-08-13","nr": "08","seite": 68,"frage": "Wozu dienen Sinus-Milieus in der Zielgruppenanalyse?","antwort": "Um Zielgruppen nach ihrer soziokulturellen Zugehörigkeit zu beschreiben, weil sie sich nicht mehr einfach nach Alter und Einkommen unterscheiden lassen."},{"id": "mko-08-14","nr": "08","seite": 75,"frage": "Wie viele Tiefeninterviews sind zu einem Projekt üblich?","antwort": "Höchstens etwa zehn, mit wenigen Usern. Das Ergebnis ist ein mentales Modell, wie User eine Aufgabe im Web angehen."},{"id": "mko-08-15","nr": "08","seite": 78,"frage": "Was sind Personas?","richtig": "Fiktive, stellvertretende Repräsentanten realer Nutzer","falsch": ["Statistische Zielgruppenbeschreibungen","Sinus-Milieus","Echte Testpersonen aus dem Usability-Labor"],"erklaerung": "Personas sind keine Zielgruppenbeschreibungen oder Milieus. Sie haben Name, Alter, Erfahrungen und Motivation und sollen dem Team Empathie für die Anwender geben."},{"id": "mko-08-16","nr": "08","seite": 82,"frage": "Wie kann KI bei der Entwicklung einer Persona helfen?","antwort": "Mit einem Prompt (z. B. an ChatGPT) lässt sich eine Persona aus einer Zielgruppe mit Geschlecht, Einkommen, Bildung, Interessen und Mediennutzung beschreiben und mit einer Bildgenerierung auch visualisieren."},{"id": "mko-08-17","nr": "08","seite": 108,"frage": "Nenne die Schritte der systematischen Layout-Entwicklung.","antwort": "Skizzen, Papier-Prototyp, Wireframes, Funktionsbeschreibungen, Layout mit Raster, fertiges Layout (Mockup), dann High-Fidelity-Prototyp."},{"id": "mko-08-18","nr": "08","seite": 116,"frage": "Worauf konzentriert man sich beim Papier-Prototyping?","antwort": "Auf die Abfolge, die Zusammenhänge und die grundsätzliche Struktur der Screens. Testen kann man iterativ in mehreren Schleifen."},{"id": "mko-08-19","nr": "08","seite": 117,"frage": "Wie läuft ein Test mit einem Papier-Prototyp ab?","antwort": "Ein Proband „klickt“ mit dem Finger auf die Elemente und denkt laut, eine dritte Person tauscht die Bestandteile entsprechend aus."},{"id": "mko-08-20","nr": "08","seite": 121,"frage": "Was zeigt ein Wireframe?","richtig": "Das grundlegende Layout der wichtigsten Elemente als Drahtgerüst in Originalgröße, ohne Farben und konkrete Bilder","falsch": ["Die detaillierte Anmutung mit Farben und Typografie","Eine voll interaktive Simulation der Anwendung","Den Zeitplan des Projekts"],"erklaerung": "Die detaillierte Anmutung zeigt erst das Mockup, die interaktive Simulation der High-Fidelity-Prototyp."},{"id": "mko-08-21","nr": "08","seite": 122,"frage": "Welche Elemente gehören in einen Wireframe?","antwort": "Logo, Kopfzeile (Header), Fußzeile (Footer), Inhaltsbereich (Content) und beispielhafte Elemente wie Bilder, Überschriften und Fließtext."},{"id": "mko-08-22","nr": "08","seite": 145,"frage": "Was ist ein Raster im Layout?","antwort": "Ein grafisches Gerüst, das der Komposition die Struktur vorgibt: Es legt Positionen und Größenverhältnisse von Objekten im Viewport fest."},{"id": "mko-08-23","nr": "08","seite": 150,"frage": "Was sind Mockups?","antwort": "Detailliert ausgearbeitete Screens, die die Anmutung visualisieren: Farben, Formen, Abstände und Typografie."},{"id": "mko-08-24","nr": "08","seite": 168,"frage": "Was ist ein Style-Guide?","antwort": "Eine modulare Zusammenfassung aller Elemente der Benutzeroberfläche, von Buttons und Formularen über Navigationsmenüs bis zu Icons. Er dokumentiert das Ergebnis und ist Werkzeug für die Weiterentwicklung."},{"id": "mko-08-25","nr": "08","seite": 174,"frage": "Wie viele Einzelinformationen können Menschen laut Gedächtnisforschung im Kurzzeitgedächtnis behalten?","richtig": "Vier bis sieben","falsch": ["Eine bis zwei","Zehn bis zwölf","Etwa zwanzig"],"erklaerung": "Daraus folgt: Komplexe Navigationsstrukturen führen zu Orientierungsproblemen, die Navigation muss überschaubar bleiben."},{"id": "mko-08-26","nr": "08","seite": 178,"frage": "Was ist Card Sorting?","antwort": "Eine schnelle Methode, die Navigationsstruktur zusammen mit Usern zu entwickeln: Probanden verteilen und gruppieren Karteikarten mit Schlagwörtern zur Website."},{"id": "mko-08-27","nr": "08","seite": 185,"frage": "Welche Bestandteile hat ein Feinkonzept?","antwort": "Inhaltsverzeichnis, Site-Map, Asset-Liste, Storyboard, Beschreibungen, Funktionsskizzen, Legende und Glossar."},{"id": "mko-08-28","nr": "08","seite": 188,"frage": "Welche Methoden für Usability-Tests nennt die Vorlesung?","antwort": "Expertenorientiert: heuristisches Gutachten. Nutzerorientiert und apparativ: Fokusgruppen und Tests im Labor mit Verhaltensbeobachtung, Mouse-Tracking und Blickaufzeichnung."},{"id": "mko-09a-01","nr": "09a","seite": 4,"frage": "Was ist die theoretische Grundlage des Interaktionsdesigns?","antwort": "Die Hypertext-Theorie: Sie funktioniert in Analogie zur Wissensspeicherung im menschlichen Gehirn, mit netzwerkartiger Struktur."},{"id": "mko-09a-02","nr": "09a","seite": 7,"frage": "Welche Bedingung muss ein Informationsknoten (Segment) erfüllen?","antwort": "Inhaltliche Geschlossenheit: Jede Einheit muss aus sich heraus verständlich sein."},{"id": "mko-09a-03","nr": "09a","seite": 11,"frage": "Was muss der User nach einer Interaktion leisten?","antwort": "Er muss den Lesefluss wieder aufnehmen, sich seiner neuen Position in der Website bewusst werden und den Bezug zur vorherigen Seite herstellen."},{"id": "mko-09a-04","nr": "09a","seite": 14,"frage": "Welche idealtypischen Interaktionsmodelle für Websites gibt es?","antwort": "Hierarchische Interaktion, lineare Interaktion, Netzmodell (freie Interaktion) und die Kombination von Leiter- und Netzstruktur."},{"id": "mko-09a-05","nr": "09a","seite": 26,"frage": "Wofür ist die lineare Navigation ideal?","richtig": "Für Bestell- und Buchungsvorgänge","falsch": ["Für eine Online-Enzyklopädie","Für das Stöbern in einer Bildsammlung","Für die Startseite eines Konzerns"],"erklaerung": "Bei Bestellungen, Buchungen und Anmeldungen werden Informationen in fester Reihenfolge abgefragt. Das ist für User leicht zu erfassen und zu bedienen."},{"id": "mko-09a-06","nr": "09a","seite": 18,"frage": "Was kennzeichnet die hierarchische Navigation?","antwort": "Sie verlinkt die Seiten in einer plausiblen Gliederung, wie im Buch. Die Informationen verfeinern sich, je tiefer der Besucher vordringt. Sie ist im Web sehr verbreitet und bewährt."},{"id": "mko-09a-07","nr": "09a","seite": 31,"frage": "Was macht ein Modal Screen?","antwort": "Er zwingt den User zu einer Entscheidung aus einer vorgegebenen Anzahl von Möglichkeiten. Sinnvoll als Hilfestellung oder um einen Vorgang in Schritte zu gliedern."},{"id": "mko-09a-08","nr": "09a","seite": 38,"frage": "Was kennzeichnet die Netzstruktur?","antwort": "Die Seiten sind ohne feste Hierarchie verlinkt. Der User hat volle Navigationsfreiheit, muss aber jederzeit wissen, wo er sich befindet."},{"id": "mko-09a-09","nr": "09a","seite": 43,"frage": "Wie lautet die richtige Entwicklungsfolge der Benutzerschnittstellen?","richtig": "CLI, GUI, NUI","falsch": ["GUI, CLI, NUI","NUI, GUI, CLI","GUI, NUI, CLI"],"erklaerung": "Zuerst die Kommandozeile (Command Line Interface), dann die grafische Oberfläche mit Maus (GUI), dann Touch- und Gestensteuerung (Natural User Interface)."},{"id": "mko-09a-10","nr": "09a","seite": 47,"frage": "Warum war die grafische Benutzeroberfläche (GUI) ein Fortschritt?","antwort": "Sie stellt deutlich geringere Anforderungen an Lern- und Erinnerungsvermögen und an den Bedienaufwand als die Kommandozeile, etwa durch Schreibtisch-Metaphern wie Ordner und Papierkorb."},{"id": "mko-09a-11","nr": "09a","seite": 51,"frage": "Was ist ein Natural User Interface (NUI)?","antwort": "Eine Benutzerschnittstelle, die ohne Hilfsmittel wie Maus oder Tastatur mit den Fingern bedient wird. Touchscreens heben die Trennung von Darstellung und Interaktion auf."},{"id": "mko-09a-12","nr": "09a","seite": 59,"frage": "Womit begann die gestengesteuerte Interaktion?","antwort": "Mit der Xbox Kinect: Eine Kamera scannt den Raum, erkennt Körperbewegungen und Sprache und steuert damit das Spiel."},{"id": "mko-09a-13","nr": "09a","seite": 75,"frage": "Wie verändern Sprachassistenten die Interaktion?","antwort": "Grundlegend: Grafische Benutzeroberflächen werden tendenziell überflüssig (Voice User Interface Design)."},{"id": "mko-09a-14","nr": "09a","seite": 76,"frage": "Was ist ein Organic User Interface (OUI)?","antwort": "Eine erforschte Schnittstelle, bei der die Interaktion mit dem Computer über elektrophysische bzw. biochemische Prozesse im Gehirn des Users erfolgt."},{"id": "mko-09b-01","nr": "09b","seite": 6,"frage": "Welche inhaltlichen Anforderungen sollte eine Homepage erfüllen?","antwort": "Den Zweck der Site kommunizieren, erste Informationen bereitstellen, weitere Inhalte beispielhaft andeuten und die Navigation anbieten."},{"id": "mko-09b-02","nr": "09b","seite": 14,"frage": "Welche zwei grundlegenden Einsichten gelten für die Homepage?","antwort": "Sie wird zuerst in Bruchteilen von Sekunden unbewusst gescannt und erst dann bewusst bewertet. Deshalb lohnt sich ihre gestalterische Optimierung besonders."},{"id": "mko-09b-03","nr": "09b","seite": 11,"frage": "Was leistet eine gut gestaltete Homepage?","antwort": "Sie macht neugierig, vermittelt, dass die folgenden Inhalte sinnvoll sind, und animiert zum Weiterklicken."},{"id": "mko-09b-04","nr": "09b","seite": 16,"frage": "Was bedeutet „Layout als Komposition der Information“?","antwort": "Alle Elemente wie Farbflächen, Texte, Grafiken, Bilder und Schaltflächen werden so zueinander angeordnet, dass eine klare Informationsordnung entsteht."},{"id": "mko-09b-05","nr": "09b","seite": 22,"frage": "Was sind inhaltliche und was funktionale Bestandteile einer Homepage?","antwort": "Inhaltlich: Logo, Titel, Texte, Bilder, Formulare, Banner. Funktional: Hauptmenü, Untermenüs, Header und Footer."},{"id": "mko-09b-06","nr": "09b","seite": 26,"frage": "Welche Aufgabe hat der Header?","richtig": "Alle zentralen Elemente zur Navigation und Orientierung bereitstellen: Logo, Hauptmenü, Metanavigation, ggf. Suche","falsch": ["Rechtliche Angaben wie Impressum sammeln","Die Website am unteren Rand abschließen","Nur das Hintergrundbild zeigen"],"erklaerung": "Der Header zeigt dem Nutzer auf den ersten Blick, dass er auf der richtigen Website ist. Impressum und weiterführende Links gehören typischerweise in den Footer."},{"id": "mko-09b-07","nr": "09b","seite": 30,"frage": "Welche Header-Elemente variieren je nach Zielsetzung der Website?","antwort": "Zum Beispiel Sprachauswahl oder Warenkorb. Pflicht sind dagegen Logo und Navigation."},{"id": "mko-09b-08","nr": "09b","seite": 37,"frage": "Welche Rolle spielen Hintergrundfarben auf der Homepage?","antwort": "Sie bringen eine erste informelle visuelle Ordnung in die Seite und gliedern Bereiche."},{"id": "mko-09b-09","nr": "09b","seite": 53,"frage": "Was ist Atomic Design?","antwort": "Ein Ansatz, der Web-Projekte als Summe kleinster Design-Bausteine versteht, aus denen Interface-Elemente wie Buttons, Textfelder und Formulare bis hin zu ganzen Seiten zusammengesetzt werden."},{"id": "mko-09b-10","nr": "09b","seite": 105,"frage": "Wovon hängt der Erfolg einer Website laut UX-Design vor allem ab?","antwort": "Nicht nur von der visuellen Gestaltung, sondern vom Erlebnis des Nutzers: Seine Erwartungen müssen in eine layoutbasierte Lösung übersetzt werden."},{"id": "mko-09b-11","nr": "09b","seite": 110,"frage": "Was bedeutet „Mobile First“?","richtig": "Das Screen-Design zuerst auf das Smartphone ausrichten, dann auf Tablet und großen Bildschirm","falsch": ["Zuerst den Desktop gestalten und dann verkleinern","Nur eine App statt einer Website bauen","Mobile Nutzer bekommen eine reduzierte Seite"],"erklaerung": "Das Smartphone ist heute das wichtigste Gerät zum Surfen. Deshalb beginnt das Design beim kleinsten Bildschirm."},{"id": "mko-09c-01","nr": "09c","seite": 7,"frage": "Wie schnell entsteht der erste, vorbewusste Eindruck einer Website?","richtig": "In weniger als 50 Millisekunden","falsch": ["In etwa 5 Sekunden","Nach rund einer Minute","Erst nach dem ersten Klick"],"erklaerung": "Was in dieser kurzen Zeit passiert, hängt eng mit den verwendeten Farben und Kontrasten zusammen."},{"id": "mko-09c-02","nr": "09c","seite": 9,"frage": "Welche Aufgabe müssen Farben im Webdesign vor allem übernehmen?","antwort": "Kommunikative Aufgaben, etwa die Aufmerksamkeit auf bestimmte Aspekte lenken. Ihr Einsatz muss gut geplant und auf die Zielgruppe abgestimmt sein."},{"id": "mko-09c-03","nr": "09c","seite": 13,"frage": "Welche Farbwahl passt zu welcher Zielgruppe?","antwort": "Bunte Farben für ein junges Publikum, frische Naturtöne und Pastell für Eltern, viel Weißraum und wenig Farbe für ein typisches Designer-Magazin, neutrale weiche Farben für Souveränität."},{"id": "mko-09c-04","nr": "09c","seite": 22,"frage": "Wozu führen harmonische und disharmonische Farbkombinationen?","antwort": "Harmonische Kombinationen werden bei vielen Menschen als angenehm empfunden, Disharmonien führen zu Unbehagen und Abneigung."},{"id": "mko-09c-05","nr": "09c","seite": 27,"frage": "Wie wirkt Weiß in Kombination mit anderen Farben?","antwort": "Es hebt die hellen, leichten Aspekte einer Farbe hervor. Als Weißraum nimmt es der Gestaltung die Schwere."},{"id": "mko-09c-06","nr": "09c","seite": 34,"frage": "Wie sollte man Rot einsetzen, wenn es nicht dominieren soll?","antwort": "Nur sparsam zur Akzentuierung, weil Rot sehr prägnant ist."},{"id": "mko-09c-07","nr": "09c","seite": 40,"frage": "Welche Farben sind die sekundären Farben?","richtig": "Orange, Grün, Violett","falsch": ["Rot, Gelb, Blau","Weiß, Grau, Schwarz","Lila, helles Grün, helles Orange"],"erklaerung": "Primärfarben (Rot, Gelb, Blau) wirken intensiv, sekundäre etwas neutraler und eleganter, tertiäre freundlich und angenehm."},{"id": "mko-09c-08","nr": "09c","seite": 44,"frage": "Wie setzt man Komplementärfarben wie Rot und Grün ein?","antwort": "Sie sind sehr lebhaft und werden kaum in voller Sättigung verwendet, eignen sich aber für situative Betonungen."},{"id": "mko-09c-09","nr": "09c","seite": 54,"frage": "Welche Kontrastpaare nennt die Vorlesung?","antwort": "Zum Beispiel Hell-Dunkel, Bunt-Unbunt und Kalt-Warm. Kontrast ist immer vom Kontext abhängig."},{"id": "mko-09c-10","nr": "09c","seite": 62,"frage": "Was ist ein monochromes Farbschema?","richtig": "Mehrere Farben desselben Farbtons, nur Helligkeit oder Sättigung variieren","falsch": ["Zwei Farben, die sich im Farbkreis gegenüberliegen","Farben, deren Farbton jeweils um denselben Wert verschoben ist","Nur die unbunten Farben Weiß, Grau und Schwarz"],"erklaerung": "Monochrom wirkt ruhig und dezent. Gegenüberliegende Farben bilden ein komplementäres Schema, gleichmäßig verschobene Farbtöne ein analoges."},{"id": "mko-09c-11","nr": "09c","seite": 66,"frage": "Was kennzeichnet ein komplementäres Farbschema?","antwort": "Zwei Farbtöne, die sich im Farbkreis gegenüberliegen. Die Kombination bietet großen Kontrast und ist sehr auffällig."},{"id": "mko-09c-12","nr": "09c","seite": 73,"frage": "Was beeinflusst die Farbwahrnehmung eines Menschen?","antwort": "Lebenslange Erfahrungen mit Farben in der Umwelt, kulturell beliebte und unbeliebte Farben und die Prägung durch erfolgreiche farbige Markenwelten."},{"id": "mko-09c-13","nr": "09c","seite": 84,"frage": "Welche Assoziationen weckt Blau laut Farbpsychologie?","richtig": "Weite, Harmonie, Ausgeglichenheit, Kühle","falsch": ["Aktivität, Energie, Gefahr","Wachstum, Frische, Natur","Trauer, Schwere, Eleganz"],"erklaerung": "Rot steht für Aktivität und Energie, Grün für Wachstum und Frische, Schwarz für Trauer, Schwere und Eleganz."},{"id": "mko-09c-14","nr": "09c","seite": 95,"frage": "Wie viele Farben sollte eine Website verwenden?","antwort": "Nicht mehr als unbedingt nötig, weil Buntheit schnell konfus wirkt. Fünf Farben gelten schon fast als zu viel."},{"id": "mko-09c-15","nr": "09c","seite": 96,"frage": "Welche Farben eignen sich für große Hintergrundflächen?","antwort": "Mit Weiß aufgehellte Farben geringer Sättigung. Hochgesättigte, intensive Farben sind nicht zu empfehlen."},{"id": "mko-09d-01","nr": "09d","seite": 7,"frage": "Wodurch wird die Lesbarkeit eines Textes bestimmt?","antwort": "Durch Schriftfont, Schriftgröße, Schriftcharakter, Buchstaben- und Wortabstände, Zeilenlänge und Zeilenabstand."},{"id": "mko-09d-02","nr": "09d","seite": 12,"frage": "Was unterscheidet Antiqua- von Groteskschriften?","antwort": "Antiqua hat Serifen und ausgeprägte Unterschiede in der Strichstärke. Grotesk (z. B. Arial, Verdana) hat gleichmäßige Strichstärke und keine Serifen."},{"id": "mko-09d-03","nr": "09d","seite": 13,"frage": "Warum eignet sich Verdana besonders für Bildschirme?","antwort": "Sie wurde eigens für die Darstellung auf dem Bildschirm entwickelt und ist auch in kleinen Schriftgraden noch sehr gut lesbar."},{"id": "mko-09d-04","nr": "09d","seite": 18,"frage": "Wie viele Schriften sollte man kombinieren?","antwort": "Wenige: Zwei Schriftarten sind fast immer genug, eine für Überschriften und eine für Fließtext."},{"id": "mko-09d-05","nr": "09d","seite": 19,"frage": "Warum ist Blocksatz im Web problematisch?","antwort": "Weil die Breite der Browserfenster von Anwender zu Anwender verschieden ist. Das kann zu großen Lücken zwischen Wörtern und Buchstaben führen."},{"id": "mko-09d-06","nr": "09d","seite": 20,"frage": "Wie lang sollte eine Textzeile auf einer Website sein?","richtig": "60 bis 80 Zeichen","falsch": ["20 bis 30 Zeichen","120 bis 150 Zeichen","So breit wie das Browserfenster"],"erklaerung": "Zu kurze Zeilen zwingen zu häufigem Zeilenwechsel und ermüden, zu lange erschweren das Finden der nächsten Zeile."},{"id": "mko-09d-07","nr": "09d","seite": 28,"frage": "Warum braucht weiße Schrift auf dunklem Grund (Negativschrift) mehr Abstand?","antwort": "Sie ist schwerer zu lesen und braucht mehr Laufweite und Zeilenabstand als dunkler Text auf hellem Grund, im Beispiel 200 % Zeilenabstand."},{"id": "mko-09d-08","nr": "09d","seite": 32,"frage": "Was gefährdet die Lesbarkeit im Zusammenspiel von Schrift und Hintergrund?","antwort": "Zu geringer Kontrast, zu lebhaft strukturierte Hintergründe und bestimmte Farbkombinationen von Text und Hintergrund."},{"id": "mko-09d-09","nr": "09d","seite": 42,"frage": "Was sind Webfonts?","antwort": "Schriften, die auf einem Server bereitgestellt und beim Aufruf geladen werden, sodass auch nicht installierte Schriften angezeigt werden. Bekannte Dienste: Adobe Typekit und Google Fonts."},{"id": "mko-09d-10","nr": "09d","seite": 48,"frage": "Was versteht man unter Weißraum?","antwort": "Sämtliche Freiräume, die die einzelnen Designelemente einer Seite voneinander trennen. Weißraum verleiht einer Seite Klarheit."},{"id": "mko-09d-11","nr": "09d","seite": 57,"frage": "Woran erkennt man gute Webtypografie?","antwort": "Man bemerkt sie kaum, weil sich der Text leicht lesen lässt. Schlechte Typografie fällt dagegen immer auf."},{"id": "mko-09e-01","nr": "09e","seite": 14,"frage": "Welche Aufgabe haben Buttons?","antwort": "User möglichst reibungslos durch eine Anwendung leiten und sie beim Ausführen gewünschter Aktionen unterstützen."},{"id": "mko-09e-02","nr": "09e","seite": 16,"frage": "Wie signalisiert man eine Button-Hierarchie?","antwort": "Mit Farben: Primäre, wichtigere Buttons sind auffälliger gestaltet als sekundäre."},{"id": "mko-09e-03","nr": "09e","seite": 19,"frage": "Wo haben sich in Online-Shops die Buttons zum nächsten Schritt bewährt?","richtig": "Rechts und insbesondere unten","falsch": ["Links oben","In der Mitte des Headers","Im Footer neben dem Impressum"],"erklaerung": "Buttons sollen so platziert sein, dass man sie nicht übersieht. Dabei sind kulturelle Konventionen zu beachten, etwa die Leserichtung."},{"id": "mko-09e-04","nr": "09e","seite": 31,"frage": "Welche Eigenschaften hat eine Mikro-Animation?","antwort": "Sie verdeutlicht einen Status bzw. gibt visuelles Feedback und vermittelt dem Nutzer das Gefühl, die Kontrolle zu haben, z. B. dass eine Eingabe registriert wurde."},{"id": "mko-09e-05","nr": "09e","seite": 46,"frage": "Warum braucht man Icons?","antwort": "User scannen Seiten mit raschen Augenbewegungen. Icons begleiten den Inhalt und erleichtern die Orientierung durch unkomplizierte visuelle Zeichen."},{"id": "mko-09e-06","nr": "09e","seite": 101,"frage": "Welche Vorteile haben Bilder auf Websites?","antwort": "Sie sprechen Nutzer direkt und emotional an, übermitteln schnell viele Informationen und lockern Texte auf."},{"id": "mko-09e-07","nr": "09e","seite": 102,"frage": "Welche Nachteile können Bilder haben?","antwort": "Nutzer ignorieren Bilder ohne relevante Information, und ein schlechtes Foto kann einen sonst positiven Gesamteindruck zerstören."},{"id": "mko-09e-08","nr": "09e","seite": 78,"frage": "Was war der adidas Urban Art Guide?","antwort": "Der weltweit erste Street-Art-Kunstführer fürs iPhone und die erste App von adidas, zum 60. Geburtstag 2009. Nutzer konnten Kunstwerke erkunden, bewerten, kommentieren und hochladen."},{"id": "mko-09e-09","nr": "09e","seite": 71,"frage": "Was machte „Alice for the iPad“ besonders?","antwort": "Statt Animationen reagieren Simulationen wie mechanisches Spielzeug auf Berühren, Kippen und Schütteln. So erweitert die App das Leseerlebnis, ohne die Intention des Buchs zu verlieren."},{"id": "mko-09f-01","nr": "09f","seite": 7,"frage": "Welche etablierten Navigationsstrategien gibt es?","antwort": "Vorwärtsgerichtet: Weiter-Button, Menüs, Suche. Rückwärtsgerichtet: Zurück-Button im Browser, Home-Button."},{"id": "mko-09f-02","nr": "09f","seite": 10,"frage": "Was bedeutet „Lost in Hyperspace“?","antwort": "Den Verlust der Orientierung in der Navigationsstruktur einer Website, weil Menschen nur vier bis sieben Informationen im Kurzzeitgedächtnis behalten."},{"id": "mko-09f-03","nr": "09f","seite": 15,"frage": "Warum platziert Amazon die Suche prominent oben in der Mitte?","antwort": "Weil sehr viele Nutzer über die Suchfunktion navigieren."},{"id": "mko-09f-04","nr": "09f","seite": 18,"frage": "Wohin schaut ein Nutzer im dritten Blick-Schritt auf einer unbekannten Webpage?","richtig": "In die Mitte des Bildschirms, wo er den eigentlichen Inhalt vermutet","falsch": ["In den oberen Bereich („Wo bin ich?“)","Auf die rechte Seite","In den Footer"],"erklaerung": "Erst der obere Bereich, dann die Navigation, dann die Mitte. Die rechte Seite wird von vielen Nutzern eher ignoriert."},{"id": "mko-09f-05","nr": "09f","seite": 25,"frage": "Welche Eigenschaften sollte eine Navigation haben?","antwort": "Erwartungskonform und intuitiv verständlich: klare Struktur, einfache Bedienung und ständige Sichtbarkeit."},{"id": "mko-09f-06","nr": "09f","seite": 26,"frage": "Wie unterscheiden sich globale und lokale Navigation?","antwort": "Die primäre bzw. globale Navigation ist als Hauptnavigation immer sichtbar. Die lokale Navigation ist themenbezogen und oft nur situativ sichtbar."},{"id": "mko-09f-07","nr": "09f","seite": 40,"frage": "Was ist ein Mega-Drop-down?","antwort": "Ein Aufklappmenü mit sehr vielen Inhalten, auch Mega-Fly-out genannt."},{"id": "mko-09f-08","nr": "09f","seite": 63,"frage": "Wann eignet sich auf dem Smartphone die Darstellung der Navigationspunkte untereinander?","antwort": "Nur für Sites mit sehr wenigen Navigationspunkten, weil sie sofort sichtbar ist, aber viel Platz im Viewport einnimmt."},{"id": "mko-09f-09","nr": "09f","seite": 73,"frage": "Was ist ein Nachteil der Burger-Navigation?","richtig": "Die Menüpunkte sind versteckt, müssen erst aufgerufen und gemerkt werden","falsch": ["Sie nimmt den ganzen Bildschirm dauerhaft ein","Sie funktioniert nur auf Desktop-Rechnern","Sie lässt keine Unterpunkte zu"],"erklaerung": "Das Aufrufen kostet eine Interaktion, und weil die Punkte nach dem Schließen verschwinden, belastet die Orientierung das Arbeitsgedächtnis."},{"id": "mko-09f-10","nr": "09f","seite": 76,"frage": "Was ist eine Off-Canvas-Navigation?","antwort": "Ein Menü, das seitlich außerhalb des Anzeigebereichs liegt und meist von rechts hereinfährt, wobei es den Inhalt zur Seite schiebt."},{"id": "mko-09f-11","nr": "09f","seite": 79,"frage": "Was ist ein Navigationshub?","antwort": "Eine Seite, die sofort die zentralen Menüpunkte enthält, häufig der Startbildschirm von Apps. Für einen anderen Menüpunkt muss man zum Hub zurückkehren."},{"id": "mko-09f-12","nr": "09f","seite": 86,"frage": "Welche Vor- und Nachteile haben Akkordeons?","antwort": "Vorteil: Sie gehören zu den gelernten Elementen und machen umfangreiche Inhalte schnell überblickbar. Nachteil: höherer Interaktionsaufwand, weil man jeden Bereich einzeln öffnen muss."},{"id": "mko-09f-13","nr": "09f","seite": 102,"frage": "Wie unterscheiden sich primäre, sekundäre und tertiäre Navigation?","antwort": "Primär: erste Auswahlebene, immer sichtbar. Sekundär: zweite Ebene, meist erst nach Aufruf. Tertiär: dritte Ebene darunter."},{"id": "mko-09f-14","nr": "09f","seite": 104,"frage": "Wozu dient eine Breadcrumb-Navigation?","antwort": "Sie unterstützt den User bei der Rückwärts-Orientierung, indem sie den Pfad zur aktuellen Seite zeigt."},{"id": "mko-09f-15","nr": "09f","seite": 112,"frage": "Wie sollte man Themenbühnen einsetzen?","antwort": "Als auflockerndes Element, aber nicht als Ersatz für die Navigation oder als alleiniger Träger wichtiger Informationen."},{"id": "mko-09g-01","nr": "09g","seite": 17,"frage": "Was ist ein Gestaltungsraster?","antwort": "Ein Gitternetz zur strukturierten Anordnung von Content- und Designelementen in Spalten, Zeilen und Zellen. Für den Nutzer wirkt das Layout dadurch geordnet."},{"id": "mko-09g-02","nr": "09g","seite": 25,"frage": "Welche Spaltenzahl wählen Webdesigner meist für ein Raster?","antwort": "Eine gerade Zahl, mit der sich gut rechnen und aufteilen lässt, häufig zwölf Spalten."},{"id": "mko-09g-03","nr": "09g","seite": 32,"frage": "In einem 12-Spalten-Raster sollen vier Objekte im Footer gleich breit stehen. Wie viele Spalten bekommt jedes?","richtig": "3","falsch": ["4","2","6"],"erklaerung": "12 Spalten geteilt durch 4 Objekte ergibt 3 Rasterspalten pro Objekt."},{"id": "mko-09g-04","nr": "09g","seite": 34,"frage": "Was kennzeichnet ein Fixed Layout?","antwort": "Es ist exakt auf eine Bildschirmgröße ausgelegt, alle Elemente sitzen auf absoluten X/Y-Koordinaten. Es eignet sich nur für ausgefeilte Gestaltungen auf definierten Displays."},{"id": "mko-09g-05","nr": "09g","seite": 36,"frage": "Was kennzeichnet ein dynamisches Layout?","antwort": "Alle Elemente werden mit Prozentwerten platziert, sodass sich das Layout an die Größe des Viewports anpasst."},{"id": "mko-09g-06","nr": "09g","seite": 37,"frage": "Was ist responsives Webdesign?","antwort": "Ein Entwicklungsansatz, der die Anzeige einer Website abhängig von Größe und Ausrichtung des Displays anpasst. Der Designer gibt dabei einen Teil der Kontrolle über das Erscheinungsbild ab."},{"id": "mko-09g-07","nr": "09g","seite": 50,"frage": "Was sind Breakpoints im responsiven Webdesign?","richtig": "Haltepunkte, an denen das Layout für eine neue Bildschirmgröße umbricht","falsch": ["Pixelgenaue Koordinaten eines Fixed Layouts","Ladefehler auf langsamen Geräten","Sprungmarken in einer One-Page"],"erklaerung": "Zwischen den Breakpoints bleibt das Design flexibel mit Prozentwerten. An ihnen ändern sich Anordnung, Priorität und manchmal sogar die Inhalte."},{"id": "mko-09g-08","nr": "09g","seite": 60,"frage": "Warum greift responsives Webdesign in die Content-Strategie ein?","antwort": "Weil man entscheiden muss, welche Inhalte in welchem Nutzungskontext wichtig sind und ob alle Nutzer auf allen Geräten dieselben Inhalte sehen sollen."},{"id": "mko-09g-09","nr": "09g","seite": 65,"frage": "Was ist das Fazit zu responsivem Webdesign?","antwort": "Es ist immer ein Kompromiss: Im Vordergrund steht nicht Top-Design, sondern die technische Übertragbarkeit auf viele Geräte."},{"id": "mko-09h-01","nr": "09h","seite": 4,"frage": "Was ist eine One-Page-Site?","antwort": "Eine Website, bei der alle Inhalte in einem einzigen langen HTML-Dokument präsentiert werden, im Gegensatz zur klassischen Site aus vielen verlinkten Unterseiten."},{"id": "mko-09h-02","nr": "09h","seite": 9,"frage": "Warum empfinden viele Nutzer One-Pages als weniger anstrengend?","antwort": "Sie müssen sich die Informationen nicht selbst zusammenklicken, sondern erhalten alles Relevante in einer vorgegebenen Abfolge. Die spielerische Rezeption macht selbst trockene Themen unterhaltsam."},{"id": "mko-09h-03","nr": "09h","seite": 10,"frage": "Auf wie viele Content-Bereiche beschränken sich One-Page-Sites meist?","richtig": "Höchstens etwa 10","falsch": ["Genau 3","Mindestens 25","Unbegrenzt viele"],"erklaerung": "Meist gibt es bis zu zehn farblich unterschiedene Bereiche in Fenstergröße."},{"id": "mko-09h-04","nr": "09h","seite": 21,"frage": "Was ist eine „Travelling Navigation“?","antwort": "Eine Navigationsleiste in einer One-Page, die beim Scrollen mitwandert. Ein Klick lädt keine neue Seite, sondern springt zum Abschnitt."},{"id": "mko-09h-05","nr": "09h","seite": 28,"frage": "Wie vermittelt man wichtige Inhalte im One-Page-Design am besten?","antwort": "Im Kontext einer passenden Geschichte (Storytelling), etwa wie bei „Every Last Drop“ zum Wasserverbrauch im Alltag."},{"id": "mko-09i-01","nr": "09i","seite": 6,"frage": "Was bedeutet Segmentierung im One-Page-Design?","antwort": "Die Zerlegung eines Inhalts oder einer Erzählung in einzelne Segmente, Abschnitte und Elemente, jeweils etwa so groß wie das Browserfenster."},{"id": "mko-09i-02","nr": "09i","seite": 15,"frage": "Warum unterstützt die Segmentierung das Lernen?","antwort": "Es werden nur so viele Informationen auf einmal gezeigt, wie das Arbeitsgedächtnis gleichzeitig problemlos verarbeiten kann."},{"id": "mko-09i-03","nr": "09i","seite": 17,"frage": "Was bedeutet Sequenzierung?","antwort": "Die Präsentation von Informationen in einer sinnvollen Abfolge von Lernschritten, bei der die Abschnitte aufeinander aufbauen."},{"id": "mko-09i-04","nr": "09i","seite": 22,"frage": "Welchen Vorteil hat die lineare Navigation in One-Pages?","richtig": "Sie reduziert die kognitive Belastung, weil weniger Auswahlentscheidungen nötig sind","falsch": ["Sie bietet maximale Navigationsfreiheit","Sie spart Speicherplatz auf dem Server","Sie ersetzt das Storytelling"],"erklaerung": "Durch lineares Scrollen ist sichergestellt, dass alle Inhalte in sinnvoller Reihenfolge ankommen, und der Aufwand für Selektionsvorgänge sinkt deutlich."},{"id": "mko-09i-05","nr": "09i","seite": 25,"frage": "Wie können One-Pages ihre starre lineare Struktur ausgleichen?","antwort": "Als linear-nonlineare Mischform: Innerhalb eines Segments gibt es interaktive Klickmöglichkeiten, und man kann zwischen Segmenten springen. Das gibt ein Gefühl selbstbestimmter Aktivität."},{"id": "mko-09i-06","nr": "09i","seite": 37,"frage": "Was ist Parallax Scrolling?","antwort": "Ein visueller Effekt, bei dem sich beim Scrollen einzelne Bildebenen und Objekte unterschiedlich schnell bewegen und so Tiefe entsteht."},{"id": "mko-09i-07","nr": "09i","seite": 41,"frage": "Wozu dienen Metaphern und Narrationen in One-Pages?","antwort": "Sie stellen Bedeutungszusammenhänge her und aktivieren beim User vorhandene Schemata, zum Beispiel die Metapher einer Reise."},{"id": "mko-09i-08","nr": "09i","seite": 50,"frage": "Wodurch entsteht der „Joy of Use“ bei One-Pages?","antwort": "Durch die Integration visueller, narrativer und metaphorischer Erzählstrategien."},{"id": "mko-10-01","nr": "10","seite": 3,"frage": "Was verlangt die Prüfungsaufgabe Medienkonzeption?","antwort": "Ein Projekt mit verschiedenen Online-Medien zu konzipieren und dabei die relevanten Entwicklungsmethoden der Medienkonzeption zu erläutern."},{"id": "mko-10-02","nr": "10","seite": 4,"frage": "Welche zentralen Online-Medien gehören in die Prüfungskonzeption?","antwort": "Website (Homepage und Funktionsseiten), Mobile Site, eine One-Page für eine spezielle Funktion und eine Smartphone-App."},{"id": "mko-10-03","nr": "10","seite": 5,"frage": "Welche weiteren Online-Medien gehören in die Prüfungskonzeption?","antwort": "Ein Newsletter, zwei Social-Media-Sites (Instagram, TikTok oder YouTube) und ein Storyboard für ein Branded Web-Video."},{"id": "mko-10-04","nr": "10","seite": 9,"frage": "Welche Analysen zur Zielgruppe verlangt die Prüfungsaufgabe?","antwort": "Eine Zielgruppenanalyse mit allgemeiner Begründung, eine Zielgruppenbeschreibung mit konkreten Daten und eine Persona."},{"id": "mko-10-05","nr": "10","seite": 11,"frage": "Welche Stufen der Gestaltung sind für die Homepage abzugeben?","antwort": "Funktionsbeschreibung, Papierzeichnung/Skizzen, Wireframe, Gestaltungsraster, dann ein Mockup mit Farben, Fonts und Schaltflächen."}]}};
